# Lunar Konstruksi - Fase 7.6 Grid & Media Polish
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Phase([string]$Message) { Write-Host "[FASE 7.6] $Message" -ForegroundColor Cyan }
function Fail([string]$Message) { Write-Host "[FASE 7.6] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Decode([string]$Value) { [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value)) }
function Write-Utf8([string]$Path,[string]$Content) { $parent=Split-Path -Parent $Path; if($parent -and -not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Force -Path $parent|Out-Null}; $enc=New-Object System.Text.UTF8Encoding($false); [System.IO.File]::WriteAllText($Path,$Content,$enc) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if(-not $repoRoot){Fail "Jalankan dari repository Lunar Konstruksi."}
$repoRoot=$repoRoot.Trim(); Set-Location $repoRoot
$required=@("components/site/redesign/archive/archive-home.tsx","components/site/redesign/archive/archive-page-renderer.tsx","components/site/redesign/archive/archive-ui.tsx","components/site/redesign/public-helpers.ts","features/public-site/server.ts")
$missing=@($required|Where-Object{-not(Test-Path -LiteralPath $_)}); if($missing.Count -gt 0){$missing|ForEach-Object{Write-Host " - $_"}; Fail "Field Archive/Fase 7.5 belum lengkap."}
$homeSource=[System.IO.File]::ReadAllText((Join-Path $repoRoot "components/site/redesign/archive/archive-home.tsx")); if($homeSource -notmatch "ArchiveHome"){Fail "archive-home.tsx tidak sesuai baseline Field Archive."}
$stamp=Get-Date -Format "yyyyMMdd-HHmmss"; $backup=Join-Path $repoRoot ".lunar-backups/phase7_6-$stamp"; New-Item -ItemType Directory -Force -Path $backup|Out-Null
$backupFiles=@("components/site/redesign/archive/archive-home.tsx","components/site/redesign/archive/archive-page-renderer.tsx","components/site/redesign/public-helpers.ts"); foreach($file in $backupFiles){$dest=Join-Path $backup $file; $parent=Split-Path -Parent $dest; New-Item -ItemType Directory -Force -Path $parent|Out-Null; Copy-Item -LiteralPath (Join-Path $repoRoot $file) -Destination $dest -Force}
Phase "Backup dibuat: $backup"
Phase "Menerapkan asymmetric grids dan media resolver..."
$payload=@{}
$payload["PHASE7_6_GRID_MEDIA_POLISH.md"]=""
$payload["components/site/redesign/archive/archive-home.tsx"]=""
$payload["components/site/redesign/archive/archive-page-renderer.tsx"]=""
$payload["components/site/redesign/public-helpers.ts"]=""
foreach($entry in $payload.GetEnumerator()){Write-Utf8 (Join-Path $repoRoot $entry.Key) (Decode $entry.Value); Write-Host "[FASE 7.6] write $($entry.Key)" -ForegroundColor DarkGray}
Write-Host ""; Write-Host "[FASE 7.6] Selesai." -ForegroundColor Green
Write-Host "Home: Project/Service/Team -> asymmetric bento grid" -ForegroundColor Green
Write-Host "About/Services/Projects -> collection-aware bento grid" -ForegroundColor Green
Write-Host "Media resolver diperluas; data CMS tetap prioritas." -ForegroundColor Green
Write-Host "Tidak ada dependency baru." -ForegroundColor Green
Write-Host ""; Write-Host "Validasi:" -ForegroundColor Cyan; Write-Host "  npm run dev"; Write-Host "  npm run typecheck"; Write-Host "  npm run build"; Write-Host "  git diff --check"
